class CartState extends Equatable {
  const CartState(this.items);
  final List<String> items;

  @override
  List<Object> get props => [items];
}

class CartCubit extends Cubit<CartState> {
  CartCubit() : super(CartState([]));

  void add(String item) {
    state.items.add(item); // changes the list the UI already shows
    emit(state); // same instance, equal to itself: ignored
  }
}

class CartState extends Equatable {
  // An unmodifiable copy: mutating it throws instead of failing silently
  CartState(List<String> items) : items = List.unmodifiable(items);
  final List<String> items;

  @override
  List<Object> get props => [items];
}

class CartCubit extends Cubit<CartState> {
  CartCubit() : super(CartState(const []));

  // A new list in a new state, so old and new aren't equal
  void add(String item) => emit(CartState([...state.items, item]));
}
